// === Tab: mySketch ===
// attractor_1.0

let N = 4000 ; let M = 10 ;

let X[] = new Array(N) ; let Y[] = new Array(N) ;
let CX[] = new Array(N) ; let CY[] = new Array(N) ; let R[] = new Array(M) ;
let dX ; let dY ; let I ; let II ; let L ; let KX ; let KY ;



function setup(){

  createCanvas(1112, 834) ; noSmooth() ; background(0) ; stroke(255,0,0) ; fill(0,0,0,2) ;
  colorMode(HSB, 255);
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(-556,+556) ; Y[I] = random(-417,+417) ;
  }

  for ( I = 0 ; I < M ; I++ ){
    R[I] = random(+60,+200) ; CX[I] = random(-556+R[I],+556-R[I]) ; CY[I] = random(-417+R[I],+417-R[I]) ; 
  }

} // setup()



function draw(){

  //rect(-1,-1,601,601) ;

  for ( I = 0 ; I < N ; I++ ){
    dX = 0 ; dY = 0 ; 
    for ( II = 0 ; II < M ; II++ ){
      KX = X[I]-CX[II] ; KY = Y[I]-CY[II] ;
      L = sqrt((KX*KX)+(KY*KY)) ;
      dX = dX + ((KX-KY-(KX*((KX*KX)+(KY*KY))/pow(R[II],2)))/pow(L,5)) ;
      dY = dY + ((KX+KY-(KY*((KX*KX)+(KY*KY))/pow(R[II],2)))/pow(L,5)) ;
    }
    L = sqrt((dX*dX)+(dY*dY)) ;
    dX = 2*dX/L ; dY = 2*dY/L ;
		stroke(I/N*255, 255, 255);
    line(X[I]+556,Y[I]+417,X[I]+dX+556,Y[I]+dY+417) ;
    X[I] = X[I] + dX ; Y[I] = Y[I] + dY ;
  }

} // draw()



function mousePressed(){ save('pix.jpg'); }

